import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"14、【大有】 乾下离上","description":"周易集注 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"周易集注 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/jizhu/018.md","filePath":"zh/classics/jizhu/018.md"}'),l={name:"zh/classics/jizhu/018.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><p>大有者，所有之大也。火在天上，万物毕照，所照皆其所有，大有之象也。一柔居尊，众阳并从，诸爻皆六五之所有，大有之义也。《序卦》“与人同者，物必归焉，故受之以大有”，所以次同人。</p><p>《彖》曰：大有，柔得尊位，大中而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。</p><p>以卦综释卦名，以卦德卦体释卦辞。大有综同人，柔得尊位而大中者，同人下卦之离往于大有之上卦，得五之尊位，居大有之中，而上下五阳皆从之也。上下从之，则五阳皆其所有矣。阳大阴小，所有者皆阳，故曰大有。内刚健则克胜其私，自诚而明也;外文明则灼见其理，自明而诚也。上下应之者，众阳应乎六五也。应天时行者，六五应乎九二也。时者，当其可之谓。天即理也，天之道，不外时而已。应天时行，如天命有德，则应天而时章之;天讨有罪，皆应天而时用之是也。乾为天，因应干，故发此句。时行即应天之实，非时行之外别有应天也。刚健文明者德之体，应天时行者德之用。有是德之体用，则能亨其大有矣，是以元亨。</p><h3 id="《象》曰-火在天上-大有-君子以遏恶扬善-顺天休命。" tabindex="-1">《象》曰：火在天上，大有，君子以遏恶扬善，顺天休命。 <a class="header-anchor" href="#《象》曰-火在天上-大有-君子以遏恶扬善-顺天休命。" aria-label="Permalink to “《象》曰：火在天上，大有，君子以遏恶扬善，顺天休命。”">​</a></h3><p>火在天上无所不照，则善恶毕照矣。遏恶者，五刑五用是也。扬善者，五服五章是也。休，美也。天命之性，有善无恶，故遏恶扬善者，正所以顺天之美命也。</p><p>初九，无交害，匪咎，艰则无咎。</p><p>害者，害我之大有也。离为戈兵，应爻戈兵在前，恶人伤害之象也，故睽卦离在前，亦曰见恶人。夬乃同体之卦，二爻变离，亦曰莫夜有戎。初居下位，以凡民而大有，家肥屋润，人岂无害之理?离火克干金，其受害也必矣。无交害者，去离尚远，未交离之境也。九三交离境，故曰小人害也。九三害字人此害字来。匪咎者，人来害我，非我之咎也。艰者，艰难以保其大有，如夬之惕号也。</p><p>初九居卑，当大有之初，应爻离火，必有害我之干金者。然阳刚得正，去离尚远，故有无交害匪咎之象。然或以匪咎而以易心处之，则必受其害矣。惟艰，则可保其大有而无咎也，故又教占者以此。</p><h3 id="《象》曰-大有初九-无交害也。" tabindex="-1">《象》曰：大有初九，无交害也。 <a class="header-anchor" href="#《象》曰-大有初九-无交害也。" aria-label="Permalink to “《象》曰：大有初九，无交害也。”">​</a></h3><p>时大有而当其初，所以去离远而无交害。</p><p>九二，大车以载，有攸往，无咎。</p><p>干错坤，为大舆，大车之象也。阳上行之物，车行之象也。以者用也，用之以载也。变离错坎，坎中满，以载之象也。大车以载之重，九二能任重之象也。二变中爻成巽，巽为股，巽错震为足，股足震动，有攸往之象也。</p><p>九二当大有之时，中德蓄积，充实富有，乃应六五之交孚，故有大车以载之象。有所往而如是则可以负荷其任，佐六五虚中之君，共济大有之盛，而无咎矣，故其占如此。</p><h3 id="《象》曰-大车以载-积中不败也。" tabindex="-1">《象》曰：大车以载，积中不败也。 <a class="header-anchor" href="#《象》曰-大车以载-积中不败也。" aria-label="Permalink to “《象》曰：大车以载，积中不败也。”">​</a></h3><p>干三连阳多之卦皆曰积，积聚之意。小畜夬皆五阳一阴同体之卦，故小畜曰积德载，此曰以载，而又曰积中者，言积阳德而居中也，则小畜之积德载愈明矣。夬九二《小象》曰得中道也，小畜九二《小象》曰，牵复在中，皆此中之意。败字在车上来，干金遇离火，必受克而败坏，故初曰无交害，三曰小人害，则败字虽从车上来，亦害字之意。曰中德所以不败坏也，曰积中不败，则离火不烧金，六五厥孚交如，与九二共济大有之太平矣。</p><p>九三，公用亨于天子，小人弗克。</p><p>三居下卦之上，故曰公。五虽阴爻，然居大位，三非正应，故称天子。亨者，阳刚居正，不以大有自私，亨之象也。卦本元亨，故曰亨。用亨于天子者，欲出而有为，以亨六五大有之治也。九二中德，止曰大车以载，不言亨于天子，而九三反欲亨于天子，何也?盖九三才刚志刚，所以用亨天子也。同人大有相综之卦，同人三四皆欲同乎二，所以大有二三皆欲共济五之大有也。小人指四也，弗克者，不能也。三欲亨于天子，四持戈兵，阻而害之，因此小人所以弗亨于天子也。盖大有之四，即同人之三，四持戈兵，即三之伏戎也。二三变为睽，舆曳牛掣，即小人之阻不能用亨也。旧注作享者非，用亨天子，犹言出而使天子亨，大有之亨也。</p><p>九三当大有之时，亦欲济亨通之会，亨于天子，而共保大有之治者也。但当离干交会之间，金受火制，小人在前，不能遽达，故有弗克，亨于天子之象。占者得此，不当如九二之有攸往也，可知矣。</p><h3 id="《象》曰-公用亨于天子-小人害也。" tabindex="-1">《象》曰：公用亨于天子，小人害也。 <a class="header-anchor" href="#《象》曰-公用亨于天子-小人害也。" aria-label="Permalink to “《象》曰：公用亨于天子，小人害也。”">​</a></h3><p>因小人害，所以弗克亨于天子，周公之无交害者，初之远于四也。孔子之小人害者，三之近于四也。</p><p>九四，匪其彭，无咎。</p><p>彭鼓声，又盛也，言声势之盛也。四变中爻为震，震为鼓，彭之象也，变艮，止*其盛之象也。</p><ul><li>原文作土，应为止之误。</li></ul><p>九四居大有之时，已过中矣，乃大有之极盛者也，近君岂可极盛。然以刚居柔，故有不极其声势之盛之象，无咎之道也。故其占如此。</p><h3 id="《象》曰-匪其彭无咎-明辩晳也。" tabindex="-1">《象》曰：匪其彭无咎，明辩晳也。 <a class="header-anchor" href="#《象》曰-匪其彭无咎-明辩晳也。" aria-label="Permalink to “《象》曰：匪其彭无咎，明辩晳也。”">​</a></h3><p>晳，明貌，晳然其明辩也，离明之象也。明辩者，辩其所居之地乃别嫌多惧之地，辩其所遇之时乃盛极将衰之时也。</p><p>六五，厥孚交如，威如吉。</p><p>威如者，恭己无为，平易而不防闲备，具特有人君之威而已。因六五其体文明，其德中顺，又有阳刚群贤辅之，即舜之无为而治矣，所以有此象。</p><p>六五当大有之世，文明中顺，以居尊位，虚己诚信，以任九二之贤。不惟九二有孚于五，而上下之阳，亦皆以诚信归之。是其孚信之交，无一毫之伪者也。是以为六五者，赖群贤以辅治，惟威如而已。此则不言而信，不怒而民威于鈇钺，盖享大有太平之福者也，何吉如之。故其象占如此。</p><h3 id="《象》曰-厥孚交如-信以发志也。威如之吉-易而无备也。" tabindex="-1">《象》曰：厥孚交如，信以发志也。威如之吉，易而无备也。 <a class="header-anchor" href="#《象》曰-厥孚交如-信以发志也。威如之吉-易而无备也。" aria-label="Permalink to “《象》曰：厥孚交如，信以发志也。威如之吉，易而无备也。”">​</a></h3><p>诚能动物，一人之信，足以发上下相信之志也。易而无备者，凡人君任贤图治，若机心深刻而过于防闲预备，则易生嫌隙，决不能与所任用之贤厥孚交如矣。惟平易而不防备，则任贤勿贰，去邪勿疑，方可享无为之治矣。威如即恭己，易而无备即无为。若依旧注作戒辞，则小象止当曰威如则吉，不应曰威如之吉也。</p><p>上九，自天祐之，吉无不利。</p><p>上九以刚明之德，当大有之盛。既有崇高之富贵，而下有六五柔顺之君，刚明之群贤辅之，上九盖无所作为，惟享自天祐助之福，吉而无不利者也。占者有是德，居是位，斯应是占矣。</p><h3 id="《象》曰-大有上吉-自天祐也。" tabindex="-1">《象》曰：大有上吉，自天祐也。 <a class="header-anchor" href="#《象》曰-大有上吉-自天祐也。" aria-label="Permalink to “《象》曰：大有上吉，自天祐也。”">​</a></h3><p>言皆天之祐助，人不可得而为也。上居天位，故曰天。此爻止有天祐之意，若系辞，又别发未尽之意也。如公用射隼，止有解悖之意。若成器而动，又未尽之意也。言各不同，皆发未尽之意。旧注泥于系辞者非。</p>',36)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
